/**
 * FreeLang Nexus Parser - 단위 테스트
 */

import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import * as AST from '../src/nexus/parser/ast';

describe('NexusParser - Phase 2 핵심 테스트', () => {
  // ==================== Test 1: V 함수 기본 파싱 ====================
  test('V 함수 기본: fn hello() {}', () => {
    const source = `@mode(v)
fn hello() {
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    expect(ast.type).toBe('Program');
    expect(ast.body.length).toBeGreaterThan(0);

    const fn = ast.body[0] as AST.VFunction;
    expect(fn.type).toBe('VFunction');
    expect(fn.name).toBe('hello');
    expect(fn.params.length).toBe(0);
    expect(fn.body.length).toBe(0);
    expect(fn.mode).toBe('v');
  });

  // ==================== Test 2: V 함수 + 파라미터 ====================
  test('V 함수: fn add(x: i64, y: i64) -> i64 { return x + y }', () => {
    const source = `@mode(v)
fn add(x: i64, y: i64) -> i64 {
  return x + y
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as AST.VFunction;
    expect(fn.name).toBe('add');
    expect(fn.params.length).toBe(2);
    expect(fn.params[0].name).toBe('x');
    expect(fn.params[0].typeAnnotation).toBe('i64');
    expect(fn.params[1].name).toBe('y');
    expect(fn.params[1].typeAnnotation).toBe('i64');
    expect(fn.returnType).toBe('i64');
    expect(fn.body.length).toBeGreaterThan(0);

    // Return 문장 확인
    const returnStmt = fn.body[0] as AST.ReturnStatement;
    expect(returnStmt.type).toBe('Return');
    expect(returnStmt.value).toBeDefined();
  });

  // ==================== Test 3: Python 함수 기본 ====================
  test('Python 함수 기본: def hello():', () => {
    const source = `@mode(python)
def hello():
  pass`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    expect(ast.type).toBe('Program');
    expect(ast.body.length).toBeGreaterThan(0);

    const fn = ast.body[0] as AST.PyFunction;
    expect(fn.type).toBe('PyFunction');
    expect(fn.name).toBe('hello');
    expect(fn.params.length).toBe(0);
    expect(fn.mode).toBe('python');
  });

  // ==================== Test 4: Python 함수 + 본문 ====================
  test('Python 함수: def add(a, b): return a + b', () => {
    const source = `@mode(python)
def add(a, b):
  return a + b`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as AST.PyFunction;
    expect(fn.name).toBe('add');
    expect(fn.params.length).toBe(2);
    expect(fn.params[0].name).toBe('a');
    expect(fn.params[1].name).toBe('b');
    expect(fn.body.length).toBeGreaterThan(0);

    // Return 문장 확인
    const returnStmt = fn.body[0] as AST.ReturnStatement;
    expect(returnStmt.type).toBe('Return');
  });

  // ==================== Test 5: 혼합 파싱 ====================
  test('혼합 모드: V 함수 + Python 함수 공존', () => {
    const source = `@mode(v)
fn fast(x: i64) -> i64 {
  return x * x
}

@mode(python)
def slow(items):
  return items`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    // V 함수 확인
    let vCount = 0;
    let pyCount = 0;

    for (const item of ast.body) {
      if ((item as any).type === 'VFunction') vCount++;
      if ((item as any).type === 'PyFunction') pyCount++;
    }

    expect(vCount).toBeGreaterThan(0);
    expect(pyCount).toBeGreaterThan(0);

    // 첫 번째가 V 함수
    const vFn = ast.body.find((item) => (item as any).type === 'VFunction') as AST.VFunction;
    expect(vFn.name).toBe('fast');
    expect(vFn.mode).toBe('v');

    // Python 함수 찾기
    const pyFn = ast.body.find((item) => (item as any).type === 'PyFunction') as AST.PyFunction;
    expect(pyFn.name).toBe('slow');
    expect(pyFn.mode).toBe('python');
  });

  // ==================== Test 6: Return 문장 파싱 ====================
  test('Return 문장: return x * x', () => {
    const source = `@mode(v)
fn square(x: i64) -> i64 {
  return x * x
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as AST.VFunction;
    const returnStmt = fn.body[0] as AST.ReturnStatement;

    expect(returnStmt.type).toBe('Return');
    expect(returnStmt.value).toBeDefined();

    // 표현식이 이항 연산식일 것
    const binaryExpr = returnStmt.value as AST.BinaryExpr;
    expect(binaryExpr.type).toBe('BinaryExpr');
    expect(binaryExpr.operator).toBe('*');
  });

  // ==================== Test 7: 할당 문장 파싱 ====================
  test('할당 문장: x = 42', () => {
    const source = `@mode(v)
fn test() {
  x = 42
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as AST.VFunction;
    const assignStmt = fn.body[0] as AST.AssignStatement;

    expect(assignStmt.type).toBe('Assign');
    expect(assignStmt.name).toBe('x');

    const value = assignStmt.value as AST.NumberLiteral;
    expect(value.type).toBe('Number');
    expect(value.value).toBe('42');
  });

  // ==================== Test 8: @mode 마커 스킵 ====================
  test('@mode 마커 스킵: 올바른 함수 생성', () => {
    const source = `@mode(v)
fn first() {
}

@mode(python)
def second():
  pass`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    // @mode 마커는 AST에 포함되지 않아야 함
    const nonModeItems = ast.body.filter((item) => (item as any).type !== 'MODE_MARKER');
    expect(nonModeItems.length).toBeGreaterThan(0);

    // 함수들이 존재
    const vFn = ast.body.find((item) => (item as any).type === 'VFunction') as AST.VFunction;
    const pyFn = ast.body.find((item) => (item as any).type === 'PyFunction') as AST.PyFunction;

    expect(vFn).toBeDefined();
    expect(pyFn).toBeDefined();
    expect(vFn.name).toBe('first');
    expect(pyFn.name).toBe('second');
  });

  // ==================== Test 9: 파라미터 타입 어노테이션 ====================
  test('Python 함수 타입 어노테이션: def calc(x: int, y: int):', () => {
    const source = `@mode(python)
def calc(x: int, y: int):
  return x + y`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as AST.PyFunction;
    expect(fn.params.length).toBe(2);
    expect(fn.params[0].typeAnnotation).toBe('int');
    expect(fn.params[1].typeAnnotation).toBe('int');
  });

  // ==================== Test 10: 표현식 파싱 ====================
  test('표현식 파싱: 연산자 우선순위 x + y * 2', () => {
    const source = `@mode(v)
fn calc() {
  return x + y * 2
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as AST.VFunction;
    const returnStmt = fn.body[0] as AST.ReturnStatement;
    const expr = returnStmt.value as AST.BinaryExpr;

    // 상위: +
    expect(expr.operator).toBe('+');

    // 우측: * 연산
    const rightExpr = expr.right as AST.BinaryExpr;
    expect(rightExpr.type).toBe('BinaryExpr');
    expect(rightExpr.operator).toBe('*');
  });
});

