  const oneCharMap: Record<string, TokenType> = {
    '(': TokenType.LPAREN,
    ')': TokenType.RPAREN,
    '{': TokenType.LBRACE,
    '}': TokenType.RBRACE,
    '[': TokenType.LBRACKET,
    ']': TokenType.RBRACKET,
    ',': TokenType.COMMA,
    '.': TokenType.DOT,
    ';': TokenType.SEMICOLON,
    ':': TokenType.COLON,
    '=': TokenType.EQUAL,
    '+': TokenType.PLUS,
    '-': TokenType.MINUS,
    '*': TokenType.STAR,
    '/': TokenType.SLASH,
    '%': TokenType.PERCENT,
    '<': TokenType.LT,
    '>': TokenType.GT,
    '!': TokenType.NOT,
    '&': TokenType.AMPERSAND,
    '|': TokenType.PIPE,
    '@': TokenType.AT,
  };

  if (ch && oneCharMap[ch]) {
    this.advance();
    return this.makeToken(oneCharMap[ch], ch, this.currentMode);
  }

  return null;
}

/**
