/**
 * FreeLang Nexus CodeGen - 단위 테스트
 */

import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';

describe('NexusCodegen - Phase 3 핵심 테스트', () => {
  // ==================== Test 1: V 함수 → C 시그니처 ====================
  test('V 함수 → C 시그니처: long long add(', () => {
    const source = `@mode(v)
fn add(x: i64, y: i64) -> i64 {
  return x + y
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('long long add(');
    expect(result.c).toContain('long long x');
    expect(result.c).toContain('long long y');
  });

  // ==================== Test 2: V 함수 → C 반환문 ====================
  test('V 함수 → C 반환: return x + y;', () => {
    const source = `@mode(v)
fn add(x: i64, y: i64) -> i64 {
  return x + y
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('return x + y;');
  });

  // ==================== Test 3: Python 함수 → Python 코드 ====================
  test('Python 함수 → Python: def slow(items):', () => {
    const source = `@mode(python)
def slow(items):
  return items`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.python).toContain('def slow(items):');
  });

  // ==================== Test 4: Python 들여쓰기 ====================
  test('Python 들여쓰기: return items', () => {
    const source = `@mode(python)
def process():
  x = 1
  return x`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    // 들여쓰기 (4칸)가 포함되어야 함
    expect(result.python).toContain('    return');
    expect(result.python).toContain('    x = 1');
  });

  // ==================== Test 5: 혼합 모드 → 분리된 출력 ====================
  test('혼합 모드: c와 python 필드 분리', () => {
    const source = `@mode(v)
fn fast(x: i64) -> i64 {
  return x * x
}

@mode(python)
def slow(items):
  return items`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('long long fast');
    expect(result.python).toContain('def slow');
    expect(result.mixed).toContain('V (C)');
    expect(result.mixed).toContain('Python');
  });

  // ==================== Test 6: 타입 변환 ====================
  test('타입 변환: i64 → long long', () => {
    const source = `@mode(v)
fn process(a: i64, b: f64) -> bool {
  return a > 0
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('long long a');
    expect(result.c).toContain('double b');
    expect(result.c).toContain('bool process');
  });

  // ==================== Test 7: 할당 문장 ====================
  test('할당 문장: C는 "long long x = 42;", Python은 "x = 42"', () => {
    const source1 = `@mode(v)
fn test() {
  x = 42
}`;
    const lexer1 = new NexusLexer(source1);
    const tokens1 = lexer1.tokenize();
    const parser1 = new NexusParser(tokens1);
    const ast1 = parser1.parse();
    const codegen1 = new NexusCodegen();
    const result1 = codegen1.generate(ast1);

    expect(result1.c).toContain('long long x = 42;');

    const source2 = `@mode(python)
def test():
  x = 42`;
    const lexer2 = new NexusLexer(source2);
    const tokens2 = lexer2.tokenize();
    const parser2 = new NexusParser(tokens2);
    const ast2 = parser2.parse();
    const codegen2 = new NexusCodegen();
    const result2 = codegen2.generate(ast2);

    expect(result2.python).toContain('x = 42');
  });

  // ==================== Test 8: 전체 파이프라인 end-to-end ====================
  test('전체 파이프라인: Lexer → Parser → Codegen', () => {
    const source = `@mode(v)
fn square(x: i64) -> i64 {
  return x * x
}

@mode(python)
def double(n):
  return n + n`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    // V 함수 확인
    expect(result.c).toContain('long long square(long long x)');
    expect(result.c).toContain('return x * x;');

    // Python 함수 확인
    expect(result.python).toContain('def double(n):');
    expect(result.python).toContain('return n + n');

    // mixed 필드도 둘 다 포함
    expect(result.mixed).toContain('long long square');
    expect(result.mixed).toContain('def double');
  });
});

