import { NexusRunner } from '../src/nexus/runtime/nexus-runner';
import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';

describe('NexusRunner - Phase 4 런타임 테스트', () => {
  const runner = new NexusRunner();

  // ==================== Test 1: C 프로그램 실행 ====================
  test('runC(): Hello World C 프로그램 실행', () => {
    const cCode = `#include <stdio.h>
int main() {
    printf("Hello, World!\\n");
    return 0;
}`;

    const output = runner.runC(cCode);

    expect(output).toContain('Hello, World!');
  });

  // ==================== Test 2: Python 프로그램 실행 ====================
  test('runPython(): Hello World Python 실행', () => {
    const pyCode = `print("Hello from Python!")
print("World")`;

    const output = runner.runPython(pyCode);

    expect(output).toContain('Hello from Python!');
    expect(output).toContain('World');
  });

  // ==================== Test 3: run() - Python만 있는 경우 ====================
  test('run(): Python 코드만 있는 CodegenResult', () => {
    const result = {
      c: '',
      python: 'print("Python only")',
      mixed: 'print("Python only")',
    };

    const runResult = runner.run(result);

    expect(runResult.pythonOutput).toContain('Python only');
    expect(runResult.cOutput).toBe('');
    expect(runResult.errors.length).toBe(0);
  });

  // ==================== Test 4: run() - C만 있는 경우 ====================
  test('run(): C 코드만 있는 CodegenResult', () => {
    const cCode = `#include <stdio.h>
int main() {
    printf("C only\\n");
    return 0;
}`;
    const result = {
      c: cCode,
      python: '',
      mixed: cCode,
    };

    const runResult = runner.run(result);

    expect(runResult.cOutput).toContain('C only');
    expect(runResult.pythonOutput).toBe('');
    expect(runResult.errors.length).toBe(0);
  });

  // ==================== Test 5: 에러 처리 ====================
  test('runC(): 잘못된 C 코드 → 컴파일 에러', () => {
    const badCode = `int main() {
    invalid syntax!!!
}`;

    expect(() => {
      runner.runC(badCode);
    }).toThrow();
  });

  // ==================== Test 6: 전체 파이프라인 end-to-end ====================
  test('전체 파이프라인: Lexer → Parser → Codegen → Runner', () => {
    // 혼합 모드 소스 코드
    const source = `@mode(v)
fn square(x: i64) -> i64 {
  return x * x
}

@mode(python)
def greet():
  print("Hello from Python")
  print("Value calculated")`;

    // Lexer → Parser → Codegen
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const codegenResult = codegen.generate(ast);

    // 코드 생성 확인
    expect(codegenResult.c).toContain('long long square');
    expect(codegenResult.python).toContain('def greet');

    // Runner에서 Python만 실행 가능 (C는 main 함수가 없음)
    // Python 실행
    const pyOutput = runner.runPython(codegenResult.python);
    expect(pyOutput).toContain('Hello from Python');
    expect(pyOutput).toContain('Value calculated');

    // C는 standalone 테스트 코드로 대체
    const cCodeWithMain = `#include <stdio.h>
long long square(long long x) {
    return x * x;
}
int main() {
    printf("%lld\\n", square(5));
    return 0;
}`;

    const cOutput = runner.runC(cCodeWithMain);
    expect(cOutput).toContain('25');
  });
});

